SELECT p.name AS process,t.name AS thread,s.name,COUNT(*) AS count,ROUND(SUM(s.dur)/1e6,2) AS total_ms,ROUND(AVG(s.dur)/1e6,3) AS avg_ms,ROUND(MAX(s.dur)/1e6,3) AS max_ms FROM slice s JOIN thread_track tt ON s.track_id=tt.id JOIN thread t ON tt.utid=t.utid LEFT JOIN process p ON t.upid=p.upid WHERE s.dur>0 AND (p.name LIKE '%bugworld%' OR p.name LIKE '%spatial%' OR p.name LIKE '%Spatial%' OR p.name LIKE '%render%') GROUP BY p.name,t.name,s.name ORDER BY total_ms DESC LIMIT 65;
